(function(){
const label='Suivi des heures',previousRender=render;let personId='',pendingImport=null;
db.timeEntries=db.timeEntries||{};db.timeTransfers=db.timeTransfers||{};
const columns=[['worked','Travail'],['extra25','HS 25 %'],['extra50','HS 50 %'],['extra100','HS 100 %'],['hc','HC'],['absence','Absence'],['meals','Paniers']];
const person=()=>people().find(p=>p.id===personId)||people()[0];
const entryKey=(p,d)=>company+'|'+p.id+'|'+d;
function rows(p){return Object.fromEntries(TimeTracking.dates(period()).map(d=>[d,db.timeEntries[entryKey(p,d)]]));}
function result(p){return TimeTracking.summarize(period(),p,rows(p));}
const f=n=>Number(n).toLocaleString('fr-FR',{maximumFractionDigits:2});
function failure(e){const out=$('#timeError');if(out)out.textContent=e.message||String(e);else toast(e.message||String(e));}
function persist(changes){const before=structuredClone(db.timeEntries),statuses=Object.fromEntries(Object.entries(db.vars).map(([k,v])=>[k,v.status]));Object.assign(db.timeEntries,changes);const touched=new Set(Object.keys(changes).map(k=>k.split('|').slice(0,2).join('|')));for(const [k,v]of Object.entries(db.vars)){const parts=k.split('|');if(v.timeTrackingSource&&touched.has(parts[0]+'|'+parts[2]))v.status='À vérifier';}if(!save()){db.timeEntries=before;for(const[k,status]of Object.entries(statuses))db.vars[k].status=status;throw Error('Enregistrement impossible. Exportez une sauvegarde.');}}

function totals(){const p=person();if(!p)return;try{const r=result(p),signature=TimeTracking.snapshot(period(),p,rows(p)),transfer=db.timeTransfers[company+'|'+period()+'|'+p.id];$('#timeTotals').innerHTML=`<div class="time-total"><span>Travail du mois</span><strong>${f(r.totals.worked)} h</strong></div><div class="time-total"><span>Heures normales</span><strong>${f(r.totals.normal)} h</strong></div><div class="time-total"><span>Heures majorées / HC</span><strong>${f(r.totals.extra25+r.totals.extra50+r.totals.extra100+r.totals.hc)} h</strong></div><div class="time-total"><span>Paniers</span><strong>${f(r.totals.meals)}</strong></div>`;$('#timeWeeks').innerHTML=`<div class="scroll"><table><tr><th>Semaine</th><th>Travail semaine entière</th><th>Dont ce mois</th><th>Normales du mois</th><th>HS 25 / 50 / 100 du mois</th><th>HC du mois</th><th>Absence du mois</th><th>Paniers du mois</th></tr>${r.weeks.map(w=>`<tr><td>${esc(w.start)} → ${esc(w.end)}</td><td>${f(w.all.worked)} h</td><td>${f(w.month.worked)} h</td><td>${f(w.month.normal)} h</td><td>${f(w.month.extra25)} / ${f(w.month.extra50)} / ${f(w.month.extra100)} h</td><td>${f(w.month.hc)} h</td><td>${f(w.month.absence)} h</td><td>${f(w.month.meals)}</td></tr>`).join('')}</table></div><p>${r.missing.length?esc(r.missing.length+' journée(s) à renseigner, y compris les jours de contexte en début/fin de semaine.'):'Toutes les journées sous contrat des semaines affichées sont renseignées.'}</p><p class="muted">${transfer?transfer.signature===signature?'Dernier transfert correspondant à cette feuille.':'Feuille modifiée : la préparation doit être transférée à nouveau.':'Pas encore transféré en préparation de paie.'}</p>`;$('#timeError').textContent='';}catch(e){failure(e);}}
function update(el){const p=person(),d=el.dataset.date,k=el.dataset.field,key=entryKey(p,d),before=db.timeEntries[key],value=el.value;try{const next={...before,[k]:value,updatedAt:new Date().toISOString()};TimeTracking.normalize(next);persist({[key]:next});totals();}catch(e){el.value=before?.[k]??'';failure(e);}}
function fillZeros(){const p=person();try{const changes={};for(const d of TimeTracking.dates(period()))if(TimeTracking.active(p,d)){const key=entryKey(p,d),row=db.timeEntries[key];if(!row||row.worked===''||row.worked==null)changes[key]={...row,worked:'0',updatedAt:new Date().toISOString()};}persist(changes);render();toast('Journées sans heures confirmées à zéro.');}catch(e){failure(e);}}
function transfer(){const p=person();try{const r=result(p);if(r.missing.length)throw Error('Complétez les journées manquantes avant le transfert.');if(p.workMode==='Forfait jours')throw Error('Le forfait jours nécessite un suivi dédié ; transfert horaire indisponible.');const v=richVar(p),s=r.totals,values={extra25:s.extra25,extra50:s.extra50,extra100:s.extra100,hcHours:s.hc,absenceHours:s.absence,mealQty:s.meals};if(Number(v.extraOther)>0)throw Error('Des heures à un autre taux sont déjà présentes en préparation. Rapprochez-les avant ce transfert pour éviter un doublon.');if(v.baseMode==='Horaire')values.hours=s.normal;const signature=TimeTracking.snapshot(period(),p,rows(p)),key=company+'|'+period()+'|'+p.id,last=db.timeTransfers[key];if(last?.signature===signature&&Object.entries(values).every(([k,n])=>Number(v[k])===n)){toast('Ces heures sont déjà transférées. Aucun ajout.');return;}extendedForm(`<h2>Transférer les heures · ${esc(p.name)}</h2><p>${esc(period())} · travail total ${f(s.worked)} h.</p><table><tr><th>Variable</th><th>Préparation actuelle</th><th>Valeur proposée</th></tr>${Object.entries(values).map(([k,n])=>`<tr><td>${esc({extra25:'HS 25 %',extra50:'HS 50 %',extra100:'HS 100 %',hcHours:'Heures complémentaires',absenceHours:'Heures d’absence',mealQty:'Paniers',hours:'Heures normales'}[k])}</td><td>${esc(v[k]??0)}</td><td>${f(n)}</td></tr>`).join('')}</table><p>Les valeurs affichées remplacent les variables correspondantes ; elles ne s’ajoutent pas. Le salaire mensuel contractuel est conservé. Les retenues d’absence et jours de congés restent à contrôler séparément.</p><label class="time-check"><input type="checkbox" name="reviewed" required> J’ai vérifié la qualification des heures, les semaines complètes, les congés et les majorations applicables. Le dimanche ne déclenche pas automatiquement +100 %.</label><label class="time-check"><input type="checkbox" name="replace" required> Je confirme le remplacement des variables affichées, y compris les valeurs à zéro.</label>`,()=>{if(TimeTracking.snapshot(period(),p,rows(p))!==signature)throw Error('La feuille a changé. Relancez le transfert.');const vk=company+'|'+period()+'|'+p.id,before=db.vars[vk],oldTransfer=db.timeTransfers[key];const prepared={...before,...values,status:'À vérifier',timeTrackingSource:{month:period(),worked:s.worked,normal:s.normal,signature,transferredAt:new Date().toISOString()}};db.vars[vk]=prepared;db.timeTransfers[key]={signature,at:new Date().toISOString(),values};db.profileHistory.push({at:new Date().toISOString(),reason:'Transfert feuille d’heures',company,person:p.id,period:period(),before:structuredClone(before||{}),after:values});if(!save()){db.vars[vk]=before;db.timeTransfers[key]=oldTransfer;db.profileHistory.pop();throw Error('Transfert non enregistré.');}});}catch(e){failure(e);}}
async function importFile(file){if(!file)return;const context={person:person().id,month:period(),company};try{if(file.size>2000000)throw Error('Fichier limité à 2 Mo.');const name=file.name.toLowerCase();let sheets;if(name.endsWith('.xlsx'))sheets=await TimeImport.xlsx(await file.arrayBuffer());else if(name.endsWith('.csv'))sheets=[{name:'CSV',rows:TimeImport.csv(await file.text())}];else throw Error('Formats acceptés : .xlsx et .csv. Pour .xls, enregistrer en .xlsx.');if(context.person!==person().id||context.month!==period()||context.company!==company)throw Error('Le salarié ou la période a changé pendant la lecture. Recommencez.');pendingImport={file:file.name,sheets,...context};extendedForm(`<h2>Choisir la feuille à importer</h2><p>${esc(file.name)} · ${esc(person().name)} · ${esc(period())}</p><label>Feuille du classeur<select name="sheet">${sheets.map((s,i)=>`<option value="${i}">${esc(s.name)}</option>`).join('')}</select></label><p class="muted">En-têtes attendus : Date, Heures travaillées, HS25, HS50, HS100, HC, Absence, Paniers, Chantier, Commentaire. Heures décimales (7,5 = 7 h 30) ; pour Excel, coller les valeurs des formules et convertir les durées en heures décimales. Aucun fichier n’est envoyé à un serveur.</p>`,form=>{const i=Number(form.get('sheet'));$('#modal').close();previewImport(i);return false;});}catch(e){failure(e);}finally{if($('#timeImport'))$('#timeImport').value='';}}
function previewImport(index){try{const p=person(),batch=pendingImport;if(!batch||batch.person!==p.id||batch.month!==period()||batch.company!==company)throw Error('Le contexte a changé. Recommencez l’import.');const sheet=batch.sheets[index],mapped=TimeImport.map(sheet.rows,{date1904:sheet.date1904,matricule:p.matricule}),allowed=new Set(TimeTracking.dates(period()));for(const r of mapped){if(!allowed.has(r.date)||!TimeTracking.active(p,r.date))throw Error(r.date+' : hors semaines affichées ou hors contrat.');TimeTracking.normalize({...db.timeEntries[entryKey(p,r.date)],...r.entry});}const beforeSignature=TimeTracking.snapshot(period(),p,rows(p));extendedForm(`<h2>Vérifier l’import des heures</h2><p>${esc(batch.file)} · ${esc(sheet.name)} · ${esc(p.name)}. ${mapped.length} journée(s).</p><div class="scroll"><table><tr><th>Date</th><th>Heures actuelles</th><th>Heures importées</th><th>HS 25 / 50 / 100</th><th>HC</th><th>Absence</th><th>Paniers</th></tr>${mapped.map(r=>`<tr><td>${esc(r.date)}</td><td>${esc(db.timeEntries[entryKey(p,r.date)]?.worked??'Non renseigné')}</td><td>${f(r.entry.worked)}</td><td>${r.entry.extra25==null?'Conservé':f(r.entry.extra25)} / ${r.entry.extra50==null?'Conservé':f(r.entry.extra50)} / ${r.entry.extra100==null?'Conservé':f(r.entry.extra100)}</td><td>${r.entry.hc==null?'Conservé':f(r.entry.hc)}</td><td>${r.entry.absence==null?'Conservé':f(r.entry.absence)}</td><td>${r.entry.meals==null?'Conservé':f(r.entry.meals)}</td></tr>`).join('')}</table></div><p>Les colonnes présentes remplacent les valeurs des dates listées. Les colonnes absentes ou vides conservent les valeurs existantes. Les autres jours sont conservés.</p><label class="time-check"><input type="checkbox" required> Je confirme le salarié, les unités et le remplacement des valeurs affichées.</label>`,()=>{if(TimeTracking.snapshot(period(),p,rows(p))!==beforeSignature)throw Error('La feuille a changé. Recommencez l’import.');const changes={};mapped.forEach(r=>{const key=entryKey(p,r.date);changes[key]={...db.timeEntries[key],...r.entry,source:batch.file,updatedAt:new Date().toISOString()};});persist(changes);pendingImport=null;});}catch(e){toast(e.message);}}
render=function(){if(view!==label)return previousRender();document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.textContent===label));const p=person();if(!p){$('#app').innerHTML=head('Suivi des heures','Ajoutez un salarié pour commencer.')+'<p>Aucun salarié dans cet établissement.</p>';return;}personId=p.id;const data=rows(p);$('#app').innerHTML=head('Les heures, du jour à la paie.','Suivi RH · sous-totaux par semaine et total mensuel · version d’essai.')+`<section class="panel time-toolbar"><label>Salarié<select id="timePerson">${people().map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select></label><button class="btn secondary" id="timeModel">Modèle CSV pour Excel</button><button type="button" class="btn" id="timeImportOpen">Importer les heures — Excel / CSV</button><input type="file" id="timeImport" accept=".xlsx,.csv" hidden><button class="btn secondary" id="timeZero">Confirmer les journées non saisies à 0 h</button><button class="btn" id="timeTransfer">Valider et transférer en préparation</button><p class="time-import-help">Importez un fichier Excel (.xlsx) ou CSV pour le salarié sélectionné. Un aperçu permet de vérifier les heures avant enregistrement. Photos, PDF et scans : non pris en charge pour le moment.</p></section><div id="timeTotals" class="time-totals"></div><p id="timeError" class="error" role="alert"></p><section class="panel"><h2>Relevé journalier · ${esc(period())}</h2><p class="muted">Heures décimales : 7,5 = 7 h 30. Le travail inclut les HS / HC ; renseignez leur ventilation sans les ajouter une seconde fois. Paniers : 0 ou 1 selon l’éligibilité réelle. Les journées grisées sont hors contrat ; les jours adjacents au mois servent à contrôler la semaine entière.</p><div class="scroll"><table class="time-sheet"><thead><tr><th>Date</th><th>Chantier</th>${columns.map(([,title])=>'<th>'+title+'</th>').join('')}<th>Commentaire</th></tr></thead><tbody>${TimeTracking.dates(period()).map(d=>{const row=data[d]||{},enabled=TimeTracking.active(p,d);return`<tr class="${!enabled?'time-disabled':!d.startsWith(period())?'time-context':''}"><td>${new Intl.DateTimeFormat('fr-FR',{weekday:'short',day:'2-digit',month:'2-digit',timeZone:'UTC'}).format(TimeTracking.day(d))}${!d.startsWith(period())?'<small>Hors mois</small>':''}</td><td><input aria-label="Chantier ${d}" data-date="${d}" data-field="site" maxlength="200" value="${esc(row.site||'')}" ${enabled?'':'disabled'}></td>${columns.map(([k,title])=>`<td><input type="number" aria-label="${title} ${d}" min="0" max="${k==='meals'?1:24}" step="${k==='meals'?1:'.01'}" data-date="${d}" data-field="${k}" value="${esc(row[k]??'')}" ${enabled?'':'disabled'}></td>`).join('')}<td><input aria-label="Commentaire ${d}" data-date="${d}" data-field="note" maxlength="500" value="${esc(row.note||'')}" ${enabled?'':'disabled'}></td></tr>`;}).join('')}</tbody></table></div></section><section class="panel" style="margin-top:16px"><h2>Sous-totaux par semaine</h2><div id="timeWeeks"></div><p class="muted">Les majorations sont qualifiées par le gestionnaire : aucun seuil universel n’est appliqué aux temps partiels, annualisations, congés, nuits ou jours fériés. Le transfert conserve la mensualisation et ne recalcule pas les bulletins historiques.</p></section>`;$('#timePerson').onchange=e=>{personId=e.target.value;render();};document.querySelectorAll('[data-field]').forEach(el=>{el.onchange=()=>update(el);});$('#timeZero').onclick=fillZeros;$('#timeTransfer').onclick=transfer;$('#timeImportOpen').onclick=()=>$('#timeImport').click();$('#timeImport').onchange=e=>importFile(e.target.files[0]);$('#timeModel').onclick=()=>download('modele-heures-'+period()+'.csv','\uFEFFDate;Heures travaillées;HS25;HS50;HS100;HC;Absence;Paniers;Chantier;Commentaire\r\n'+period()+'-01;7;0;0;0;0;0;1;Chantier exemple;Exemple à remplacer','text/csv;charset=utf-8');totals();};
const oldCreateDraft=createDraft;createDraft=function(id){const p=people().find(x=>x.id===id),source=p&&richVar(p).timeTrackingSource;if(source&&source.signature!==TimeTracking.snapshot(period(),p,rows(p))){toast('La feuille d’heures a changé : vérifiez et transférez à nouveau avant de créer le bulletin.');return;}return oldCreateDraft(id);};
const oldVariableMarkup=variableMarkup;variableMarkup=function(p){const v=richVar(p),source=v.timeTrackingSource;return oldVariableMarkup(p)+(source?section('Origine des heures',`<p class="wide">Feuille d’heures ${esc(source.month)} : ${f(source.worked)} h travaillées, dont ${f(source.normal)} h normales. Transfert du ${esc(new Date(source.transferredAt).toLocaleString('fr-FR'))}. Les variables restent modifiables.</p>`):'');};
if(![...document.querySelectorAll('#nav button')].some(b=>b.textContent===label)){const b=document.createElement('button');b.textContent=label;b.onclick=()=>go(label);const employeesButton=[...document.querySelectorAll('#nav button')].find(item=>item.textContent==='Salariés');if(employeesButton)employeesButton.after(b);else $('#nav').appendChild(b);}render();
})();
